from abq_authoring import response,notes
from pathlib import Path
import json,hashlib
p=Path('components/MarkBank/cards/business/rubric-authored.json');d=json.loads(p.read_text())
d['cards']=[c for c in d['cards'] if not (c['year']==2013 and c['section']=='3' and c['id'].split('-q')[-1][0] in ['1','2'])]
d['reviews']=[r for r in d['reviews'] if not (r['year']==2013 and r['section']=='3' and r['question'] in ['1(A),1(C)','2'])]
created=[]
def add(suffix,ref,prompt,total,topic,concept,requirements,responses,pages,guidance=None):
 c=dict(id=f'bus-2013-hl-s3-{suffix}',year=2013,level='higher',section='3',paperFileid='LC033ALP000EV',paperPages=[6],sourceLabel='QUESTION PAPER',sourceTitle=f'2013 Business · {ref}',questionRef=f'2013 HL Section 3 {ref}',questionText=prompt,totalMarks=total,topicId=topic,conceptId=concept,rubric=dict(system='business',taskRequirements=requirements,guidance=guidance or [],responses=responses,schemeFileid='LC033ALP000EV',schemePages=[7]+pages,markingGuideNote=notes))
 d['cards'].append(c);created.append(c)
add('q1a-i','Q1(A)(i)','Explain the term ‘data protection’ under the terms of the Data Protection Acts 1988 and 2003.',6,'business-0-13','data-protection',['The definition carries 4 + 2 marks. Refer to the privacy of individuals and processing of their personal data.'],[response(1,'Definition',[('explain','Explanation',4),('develop','Development',2)])],[19],['Apply the Acts named in this historical examination question.'])
add('q1a-ii','Q1(A)(ii)','Discuss the functions of the ‘data protection commissioner’ under the terms of the Data Protection Acts 1988 and 2003.',14,'business-0-13','data-protection-commissioner',['Discuss two functions at 7 marks each (4 + 3).'],[response(i,f'Function {i}',[('explain','Explanation',4),('develop','Development',3)]) for i in [1,2]],[19,20],['The Act names from Part A(i) are included here so that the task can be answered independently. Use the historical legislation named in the paper.'])
add('q1c','Q1(C)','Illustrate your understanding of the following terms in relation to a valid contract: Agreement; Legality of form; Consideration.',20,'business-0-12','essential-elements-of-a-contract',['Cover all three required terms. Agreement carries 8 marks (3 + 3 + 2); legality of form and consideration each carry 6 marks (3 + 3).'],[response(1,'Agreement',[('explain','First element of explanation',3),('develop','Second element of explanation',3),('illustration','Illustration',2)]),response(2,'Legality of form',[('explain','Explanation',3),('illustration','Illustration',3)]),response(3,'Consideration',[('explain','Explanation',3),('illustration','Illustration',3)])],[22])
add('q2a','Q2(A)','Discuss the opportunities and challenges of Partnership as a form of business ownership.',20,'business-5-14','partnership-opportunities-and-challenges',['Discuss two opportunities and two challenges. Each response carries 5 marks (2 + 3).'],[response(i,label,[('name','Point',2),('explain','Discussion',3)]) for i,label in enumerate(['Opportunity 1','Opportunity 2','Challenge 1','Challenge 2'],1)],[23])
add('q2b','Q2(B)','Outline the role of the Irish Government in encouraging and in regulating business in Ireland.',20,'business-5-15','government-encouragement-and-regulation',['Outline four points, including at least one under encouragement and one under regulation. Each carries 5 marks (2 + 3).'],[response(i,label,[('name','Point',2),('explain','Explanation',3)]) for i,label in enumerate(['Encouragement','Regulation','Additional point 1','Additional point 2'],1)],[23,24],['Use the institutions and arrangements applicable to the 2013 examination.'])
add('q2c','Q2(C)','Discuss current trends affecting businesses in the services sector of the Irish economy. Provide examples to support your answer.',20,'business-5-13','trends-in-the-services-sector',['Discuss four trends, supported with examples. Each carries 5 marks (2 + 3).'],[response(i,f'Trend {i}',[('name','Trend',2),('explain','Discussion with example',3)]) for i in range(1,5)],[25],['“Current” refers to the context of this 2013 paper; the original scheme illustrates the trends assessed at that time.'])
sources={kind:dict(fileid='LC033ALP000EV.pdf',sha256=hashlib.sha256(Path(f'paper-trail-corpus/{kind}/2013/LC033ALP000EV.pdf').read_bytes()).hexdigest()) for kind in ['exampapers','markingschemes']}
for question,boundaries,pages,selection,clarifications in [
('1(A),1(C)',{'1(A)(i)':6,'1(A)(ii)':14,'1(C)':20},[19,20,22],'Q1(A) uses open examples of functions, not a closed pool. Q1(C) requires all three contract headings; no alternatives are offered. Q1(B) is separately reviewed and mechanically expanded in route-pools.json.',['A splits at 6/14; A(ii) retains the Act names from the stem.','Q1(C) retains unequal 8/6/6 allocations.']),
('2',{'2(A)':20,'2(B)':20,'2(C)':20},[23,24,25],'Opportunities, challenges, government actions and services-sector trends are open examples. The scheme requires two opportunities and two challenges in A, and at least one encouragement and one regulation point in B. These are required categories rather than a finite answer menu.',['The paper’s introductory statement about choosing a business structure is context, not a selection instruction.','C is interpreted in the historical context of the 2013 examination.'])]:
 ids=[c['id'] for c in created if c['id'].startswith(f'bus-2013-hl-s3-q{question[0]}')]
 d['reviews'].append(dict(status='partial-subject-review',year=2013,level='higher',section='3',question=question,cardIds=ids,sources=sources,paperPagesReviewed=[6],schemePagesReviewed=[7]+pages,boundaries=boundaries,selectionAnalysis=selection,sourceClarifications=clarifications))
d['cards'].sort(key=lambda c:(c['year'],c['section'],c['id']));d['reviews'].sort(key=lambda r:(r['year'],r['section'],r['question']))
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
p=Path('data/examTopics/business-source-reviewed-topics.json');d=json.loads(p.read_text())
for r in d['questions']:
 if r['year']==2013 and r['n']=='S3Q1':
  r.pop('merge',None);r['canonicalNodeIds']=['business-0-12','business-0-13','business-0-14'];r['reason']='All parts of Q1 were visually reviewed: data protection, a finite pool of consumer and industrial-relations redress bodies, and contract elements.'
d['questions']=[r for r in d['questions'] if not (r['year']==2013 and r['n']=='S3Q2')]
d['questions'].append(dict(year=2013,level='higher',paperKey='single',n='S3Q2',canonicalNodeIds=['business-5-14','business-5-15','business-5-13'],reason='All parts of Q2 were visually reviewed: partnership, government encouragement/regulation and trends in the services sector.'))
d['questions'].sort(key=lambda r:(r['year'],str(r['n'])));p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
